    else if(a==='--contribs') o.contribs=requiredValue(args,i++,a).split(',').map(x=>x.trim()).filter(Boolean)
    else if(a==='--exclude-contrib') o.exclude=requiredValue(args,i++,a).split(',').map(x=>x.trim()).filter(Boolean)
